├── /js/
│   ├── app.js                 # Lógica principal + enrutamiento
│   ├── agents/
│   │   ├── empatia.js         # Agente emocional (local)
│   │   ├── seguridad.js       # Protocolos de crisis
│   │   ├── educacion.js       # Base científica de sustancias
│   │   └── crisis.js          # Detección + intervención
