│       └── i18n.js            # Traducciones ES/CA/EN/PT
├── /css/
│   ├── main.css               # Diseño responsive + accesibilidad WCAG AA
│   └── themes/
│       ├── dark.css
│       ├── high-contrast.css
│       └── neuro-friendly.css # Modo bajo estímulo sensorial
├── /assets/
│   ├── icons/                 # SVG optimizados
