/**
 * Módulo de intervención en crisis - Funciona 100% offline
 * Basado en protocolos de primeros auxilios psicológicos (PAP)
 */

const CRISIS_PROTOCOL = {
  // Palabras clave por idioma (expansible)
  keywords: {
    es: [
      "suicid", "morir", "matar", "acabar con todo", "no puedo más",
      "desesperado", "sin salida", "oscuro", "vacío", "cargar",
      "hacerme daño", "cortarme", "pastillas", "saltar"
    ],
    en: ["suicid", "die", "kill", "end it", "can't go on", "hopeless"],
    ca: ["suicid", "morir", "acabar", "no puc més", "desesperat"],
    pt: ["suicíd", "morrer", "acabar", "não aguento", "desespero"]
  },

  // Recursos por país (actualizable)
  resources: {
    es: {
      emergency: "112",
      suicide_prevention: "024",
      text: "Texto 'HOLA' al 600 360 77 77",
      web: "https://www.024.gob.es"
    },
    mx: {
      emergency: "911",
      suicide_prevention: "800 911 2000",
      text: "Línea de la Vida",
      web: "https://salud.gob.mx"
    },
    ar: {
      emergency: "107",
      suicide_prevention: "135",
      text: "Centro de Asistencia al Suicida",
      web: "https://www.cas.org.ar"
    },
    // ... añadir más países
  },

  // Respuestas de contención inmediata
  containment: [
    "Respira conmigo: inhala 4 segundos... mantén 4... exhala 6. Repite 3 veces.",
    "Estás a salvo en este momento. Esta sensación intensa pasará. No estás solo/a.",
    "¿Puedes nombrar 3 cosas que ves ahora mismo? 2 que escuchas? 1 que sientes en tu cuerpo?"
  ]
};

export function analyzeCrisisRisk(text, lang = 'es') {
  const lower = text.toLowerCase();
  const keywords = CRISIS_PROTOCOL.keywords[lang] || CRISIS_PROTOCOL.keywords.es;

  let score = 0;
  let matched = [];

  keywords.forEach(kw => {
    if (lower.includes(kw)) {
      score += 2;
      matched.push(kw);
    }
  });

  // Factores de intensidad
  if (/(inmediat|ahora|ya|urgent)/i.test(lower)) score += 3;
  if (/(plan|método|cómo|cuándo)/i.test(lower)) score += 5;
  if (/(solo|nadie|inútil|carga)/i.test(lower)) score += 2;

  return {
    risk: score >= 7 ? 'high' : score >= 4 ? 'medium' : 'low',
    score,
    matched,
    recommended: getRecommendation(score, lang)
  };
}

function getRecommendation(score, lang) {
  if (score >= 7) {
    return {
      action: 'immediate_contact',
      message: '⚠️ Tu seguridad es prioridad. ¿Podemos contactar a alguien de confianza ahora?',
      resources: CRISIS_PROTOCOL.resources[lang] || CRISIS_PROTOCOL.resources.es
    };
  }
  if (score >= 4) {
    return {
      action: 'containment',
      message: 'Gracias por compartir. Vamos a hacer un ejercicio breve para estabilizar. ¿Te parece?',
      technique: 'grounding_54321'
    };
  }
  return {
    action: 'monitor',
    message: 'Te escucho. Si en algún momento la intensidad sube, puedo ayudarte a conectar con apoyo profesional.'
  };
}

export function triggerCrisisPanel(resources) {
  const panel = document.getElementById('crisis-panel');
  if (!panel) return;

  panel.hidden = false;
  panel.setAttribute('aria-hidden', 'false');

  // Configurar botones
  document.getElementById('crisis-call').onclick = () => {
    window.location.href = `tel:${resources.emergency}`;
  };

  document.getElementById('crisis-close').onclick = () => {
    panel.hidden = true;
    panel.setAttribute('aria-hidden', 'true');
    // Registrar evento anónimo para mejora (local storage, no enviado)
    try {
      const logs = JSON.parse(localStorage.getItem('crisis_dismissed') || '[]');
      logs.push({ ts: Date.now(), lang: document.documentElement.lang });
      localStorage.setItem('crisis_dismissed', JSON.stringify(logs.slice(-100)));
    } catch(e) {}
  };

  // Enfocar botón principal para accesibilidad
  setTimeout(() => {
    document.getElementById('crisis-call')?.focus();
  }, 100);
}

export default { analyzeCrisisRisk, triggerCrisisPanel, CRISIS_PROTOCOL };
```

